CREATE TABLE player(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, school TEXT NOT NULL, college TEXT NOT NULL, major TEXT NOT NULL, student_number TEXT NOT NULL, profile_complete INTEGER NOT NULL CHECK(profile_complete IN (0,1)), UNIQUE(school,student_number));
CREATE TABLE staff(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE competition(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, register_start INTEGER NOT NULL, register_end INTEGER NOT NULL, competition_time INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('未开放','报名中','报名截止','比赛中','已结束')), advance_count INTEGER NOT NULL CHECK(advance_count>0), CHECK(register_start<register_end AND register_end<competition_time));
CREATE TABLE competition_category(competition_id TEXT NOT NULL REFERENCES competition(id) ON DELETE CASCADE, category TEXT NOT NULL CHECK(category IN ('民航史','飞行原理','航空法规')), PRIMARY KEY(competition_id,category));
CREATE UNIQUE INDEX one_running_competition ON competition(status) WHERE status='比赛中';
CREATE TABLE reservation(id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), competition_id TEXT NOT NULL REFERENCES competition(id), created_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT '有效' CHECK(status IN ('有效','已取消')), UNIQUE(player_id,competition_id));
CREATE TABLE registration(id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), competition_id TEXT NOT NULL REFERENCES competition(id), created_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT '有效' CHECK(status IN ('有效','已取消')), UNIQUE(player_id,competition_id));
CREATE TABLE competition_group(id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES competition(id), name TEXT NOT NULL, sequence_no INTEGER NOT NULL CHECK(sequence_no>0), UNIQUE(competition_id,name), UNIQUE(competition_id,sequence_no));
CREATE TABLE group_assignment(id TEXT PRIMARY KEY, registration_id TEXT NOT NULL UNIQUE REFERENCES registration(id), group_id TEXT NOT NULL REFERENCES competition_group(id), created_at INTEGER NOT NULL);
CREATE TABLE question(id TEXT PRIMARY KEY, content TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('民航史','飞行原理','航空法规')), option_a TEXT NOT NULL, option_b TEXT NOT NULL, option_c TEXT NOT NULL, option_d TEXT NOT NULL, correct_answer TEXT NOT NULL CHECK(correct_answer IN ('A','B','C','D')), active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE TABLE competition_round(id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES competition(id), name TEXT NOT NULL, round_type TEXT NOT NULL CHECK(round_type IN ('REQUIRED','BUZZER','RISK')), sequence_no INTEGER NOT NULL CHECK(sequence_no>0), time_limit INTEGER NOT NULL CHECK(time_limit>0), UNIQUE(competition_id,sequence_no));
CREATE TABLE round_question(id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES competition_round(id), question_id TEXT NOT NULL REFERENCES question(id), sequence_no INTEGER NOT NULL CHECK(sequence_no>0), UNIQUE(round_id,question_id), UNIQUE(round_id,sequence_no));
CREATE TABLE group_round(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES competition_group(id), round_id TEXT NOT NULL REFERENCES competition_round(id), status TEXT NOT NULL CHECK(status IN ('待开始','进行中','已完成')), UNIQUE(group_id,round_id));
CREATE TABLE question_release(id TEXT PRIMARY KEY, group_round_id TEXT NOT NULL REFERENCES group_round(id), round_question_id TEXT NOT NULL REFERENCES round_question(id), started_at INTEGER NOT NULL, deadline INTEGER NOT NULL, closed_at INTEGER, UNIQUE(group_round_id,round_question_id), CHECK(deadline>started_at));
CREATE UNIQUE INDEX one_open_release ON question_release((1)) WHERE closed_at IS NULL;
CREATE TABLE answer_record(id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES question_release(id), player_id TEXT NOT NULL REFERENCES player(id), user_answer TEXT NOT NULL CHECK(user_answer IN ('A','B','C','D')), correct INTEGER NOT NULL CHECK(correct IN (0,1)), score_change INTEGER NOT NULL, submitted_at INTEGER NOT NULL, UNIQUE(release_id,player_id));
CREATE TABLE timeout_record(id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES question_release(id), player_id TEXT NOT NULL REFERENCES player(id), settled_at INTEGER NOT NULL, UNIQUE(release_id,player_id));
CREATE TABLE result(id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES competition(id), player_id TEXT NOT NULL REFERENCES player(id), final_score INTEGER NOT NULL, ranking INTEGER NOT NULL CHECK(ranking>0), promoted INTEGER NOT NULL CHECK(promoted IN (0,1)), UNIQUE(competition_id,player_id), UNIQUE(competition_id,ranking));
CREATE INDEX answers_player ON answer_record(player_id);
PRAGMA user_version=16;
